{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "agent.completions.message.MessageExpression",
  "description": "A message with expressions for dynamic content.\n\nThis is the expression variant of [`Message`] used in function definitions\nwhere message content can be computed from the function input at runtime.\nSupports both JMESPath and Starlark expressions.",
  "anyOf": [
    {
      "title": "Developer",
      "type": "object",
      "$ref": "agent.completions.message.DeveloperMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "developer"
          ]
        }
      }
    },
    {
      "title": "System",
      "type": "object",
      "$ref": "agent.completions.message.SystemMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "system"
          ]
        }
      }
    },
    {
      "title": "User",
      "type": "object",
      "$ref": "agent.completions.message.UserMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "user"
          ]
        }
      }
    },
    {
      "title": "Assistant",
      "type": "object",
      "$ref": "agent.completions.message.AssistantMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "assistant"
          ]
        }
      }
    },
    {
      "title": "Tool",
      "type": "object",
      "$ref": "agent.completions.message.ToolMessageExpression",
      "properties": {
        "role": {
          "type": "string",
          "enum": [
            "tool"
          ]
        }
      }
    }
  ]
}

